export function tableArt(cityId) {
  const { relief, accents, landmarks } = Object.hasOwn(CITY_ART, cityId) ? CITY_ART[cityId] : CITY_ART.quito;
  return `<svg class="table-city-art" viewBox="0 0 720 240" aria-hidden="true" focusable="false">
    <g fill="none" stroke="currentColor" stroke-width="1.5" opacity=".46">${relief}</g>
    <g fill="var(--city-art-accent, #ffbd9d)" opacity=".8">${accents}</g>
    <g fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">${landmarks}</g>
  </svg>`;
}
